// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        // admin is the deploying contract (address(this)); only admin may call setOwner.
        // Keep the domain wide; just exclude the degenerate case where the argument
        // equals the admin, which would hide the difference.
        vm.assume(newOwner != address(this));

        vm.prank(address(this));
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }

        // General rule: a successful setOwner(x) makes the public owner getter return x.
        assertTrue(ok && c.owner() == newOwner);
    }
}
